    ///   - user: Explicit owning user (`usr_...`) for privileged calls.
    ///   - agent: Explicit owning agent (`agi_...`) for privileged calls.
    ///   - org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
    ///   - limit: Maximum comments to return. Capped at 100.
    ///   - afterCursor: Opaque cursor returned by the previous page.
    /// - Returns: Successful response
    public func list(task: String, team: String? = nil, user: String? = nil, agent: String? = nil, org: String? = nil, limit: Int? = nil, afterCursor: String? = nil) async throws -> CommentListResponse {
        var query: [(String, String)] = []
        if let team = team {
            query.append(("team", team))
        }
        if let user = user {
            query.append(("user", user))
        }
        if let agent = agent {
            query.append(("agent", agent))
        }
        if let org = org {
            query.append(("org", org))
        }
        if let limit = limit {
            query.append(("limit", String(limit)))
        }
        if let afterCursor = afterCursor {
            query.append(("after_cursor", afterCursor))
        }
        return try await http.request("/api/v1/tasks/\(task)/comments", query: query)
    }

    /// Create a comment on a task
    ///
    /// Posts a new comment on the specified task and returns the created comment.
    /// The task's owner is resolved from the task itself.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - input: Request body.
    /// - Returns: The newly created comment.
    public func create(task: String, input: CommentCreateInput) async throws -> TaskComment {
        return try await http.request("/api/v1/tasks/\(task)/comments", method: "POST", body: input)
    }

    /// Delete a task comment
    ///
    /// Permanently removes a comment from its task. This action cannot be undone.
    /// The task's owner is resolved from the task itself.
    /// Only the comment's author, an admin of the comment's organization, or an
    /// admin of the owning team may delete a comment. Returns `403 Forbidden`
    /// otherwise.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - comment: Comment ID (`tcm_...`).
    /// - Returns: Empty body. The server responds with HTTP 204 No Content on success.
    public func delete(task: String, comment: String) async throws {
        try await http.requestVoid("/api/v1/tasks/\(task)/comments/\(comment)", method: "DELETE")
    }

    /// Update a task comment
    ///
    /// Replaces the body of an existing comment and returns the updated comment.
    /// The task's owner is resolved from the task itself.
    /// Only the comment's author, an admin of the comment's organization, or an
    /// admin of the owning team may edit a comment. Returns `403 Forbidden`
    /// otherwise.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - comment: Comment ID (`tcm_...`).
    ///   - input: Request body.
    /// - Returns: The updated comment.
    public func replace(task: String, comment: String, input: CommentReplaceInput) async throws -> TaskComment {
        return try await http.request("/api/v1/tasks/\(task)/comments/\(comment)", method: "PUT", body: input)
    }
}

public final class LeaseResource: Sendable {
    private let http: HttpClient

    public init(http: HttpClient) {
        self.http = http
    }

    /// Release a task session lease
    ///
    /// Releases the authenticated assignee's matching live task lease. Repeating a
    /// release after the lease is absent succeeds. A different live successor lease
    /// returns a mismatch.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    /// - Returns: Empty response. HTTP 204 is returned after release is accepted.
    public func remove(task: String) async throws {
        try await http.requestVoid("/api/v1/tasks/\(task)/lease", method: "DELETE")
    }

    /// Retrieve a task's current session lease
    ///
    /// Returns the authenticated assignee's viewer-safe live lease summary, or null
    /// when no live lease exists. Fencing and opaque session identifiers are never
    /// included.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    /// - Returns: Viewer-safe live lease summary, or null.
    public func list(task: String) async throws -> TaskSessionLeaseSummary? {
        return try await http.request("/api/v1/tasks/\(task)/lease")
    }

    /// Claim a task for a coding session
    ///
    /// Atomically claims a user-assigned task for the authenticated user's coding
    /// session. The caller generates and retains both UUIDs. An exact retry returns
    /// the existing lease without extending it; another live holder produces a
    /// conflict. Developer and server-to-server credentials cannot impersonate the
    /// assigned user.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - input: Request body.
    /// - Returns: The caller-held lease, including its fencing token.
    public func create(task: String, input: LeaseCreateInput) async throws -> TaskSessionLease {
        return try await http.request("/api/v1/tasks/\(task)/lease", method: "POST", body: input)
    }

    /// Renew a task session lease
    ///
    /// Renews the authenticated assignee's matching live task lease. Both
    /// caller-generated UUIDs must match the aggregate's current lease.
    ///
    /// - Parameters:
    ///   - task: Task ID (`tsk_...`).
    ///   - input: Request body.
    /// - Returns: The renewed caller-held lease.
    public func renew(task: String, input: LeaseRenewInput) async throws -> TaskSessionLease {
        return try await http.request("/api/v1/tasks/\(task)/lease/renew", method: "POST", body: input)
    }
}

