    ///   - user: Explicit owning user (`usr_...`) for privileged calls.
    ///   - agent: Explicit owning agent (`agi_...`) for privileged calls.
    ///   - org: Explicit organization (`org_...`) for privileged calls; pass null when unscoped.
    ///   - limit: Maximum subtasks to return. Capped at 100.
    ///   - afterCursor: Opaque cursor returned by the previous page.
    /// - Returns: Successful response
    public func subtasks(task: String, team: String? = nil, user: String? = nil, agent: String? = nil, org: String? = nil, limit: Int? = nil, afterCursor: String? = nil) async throws -> TaskSubtasksResponse {
        var query: [(String, String)] = []
        if let team = team {
            query.append(("team", team))
        }
        if let user = user {
            query.append(("user", user))
        }
        if let agent = agent {
            query.append(("agent", agent))
        }
        if let org = org {
            query.append(("org", org))
        }
        if let limit = limit {
            query.append(("limit", String(limit)))
        }
        if let afterCursor = afterCursor {
            query.append(("after_cursor", afterCursor))
        }
        return try await http.request("/api/v1/tasks/\(task)/subtasks", query: query)
    }
}
